INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (3.414, "2022/04/18 15:00:00", 0.0, 190801, "カリン", "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 53, 20026, "2030/01/01 14:59:59", 1, 20026001, 1, 2, -416.5);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (3.099, "2022/04/18 15:00:00", 0.0, 190801, "カリン", "ミッションをクリアして、\n報酬をゲットしましょう！", 53, 20026, "2030/01/01 14:59:59", 1, 20026002, 2, 2, -416.5);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (2.801, "2022/04/18 15:00:00", 0.0, 190801, "カリン", "受け取ることができる\n報酬があるようです\n確認してみてください", 54, 20026, "2030/01/01 14:59:59", 1, 20026003, 3, 2, -416.5);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (0.0, "2022/04/18 15:00:00", 0.0, 190801, "カリン", "報酬がもらえますよ！\nチェックしてみてください", 54, 20026, "2030/01/01 14:59:59", 2, 20026004, 4, 2, -416.5);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (0.0, "2022/04/18 15:00:00", 0.0, 190801, "カリン", "イベントお疲れ様です！\n皆さんのご活躍ぶりには\nいつも感謝しています", 57, 20026, "2030/01/01 14:59:59", 1, 20026005, 5, 1, -416.5);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (5.506, "2022/04/18 15:00:00", 0.0, 190801, "カリン", "ギルド管理協会です！\n討伐証をお持ちでしたら、\n報酬交換できますよ", 55, 20026, "2030/01/01 14:59:59", 1, 20026006, 1, 2, -363.0);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (1.216, "2022/04/18 15:00:00", 0.0, 190801, "カリン", "お疲れ様です！\nここでは、討伐証と報酬を\n交換することができます！", 55, 20026, "2030/01/01 14:59:59", 2, 20026007, 2, 1, -363.0);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (1.539, "2022/04/18 15:00:00", 0.0, 190801, "カリン", "お疲れ様でした\n討伐証の交換、\nお忘れないように！", 56, 20026, "2030/01/01 14:59:59", 2, 20026008, 3, 1, -363.0);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (1.875, "2022/04/18 15:00:00", 0.0, 190801, "カリン", "終わっちゃいましたねー\n討伐証は努力の証！\n報酬と交換しましょう！", 56, 20026, "2030/01/01 14:59:59", 2, 20026009, 4, 1, -363.0);
